def table(data, widths, header=True, fs=None):
    d = [[Paragraph(str(c), tch if (header and i == 0) else tc) for c in r] for i, r in enumerate(data)]
    t = Table(d, colWidths=[w*cm for w in widths], repeatRows=1 if header else 0)
    st = [('GRID', (0,0), (-1,-1), 0.4, colors.HexColor('#999999')), ('VALIGN', (0,0), (-1,-1), 'TOP'), ('TOPPADDING', (0,0), (-1,-1), 2), ('BOTTOMPADDING', (0,0), (-1,-1), 2)]
    if header: st.append(('BACKGROUND', (0,0), (-1,0), colors.HexColor('#0b3c7a')))
    t.setStyle(TableStyle(st)); S.append(t); S.append(Spacer(1, 6))
